      out.write("        strokeColor: getColorByDay(day),\r\n");
      out.write("        strokeOpacity: 0.85\r\n");
      out.write("      });\r\n");
      out.write("      polyline.setMap(map);\r\n");
      out.write("      routeLines.push(polyline);\r\n");
