      out.write("        '<label style=\"flex:1; cursor: pointer; display: flex; align-items: center;\">' +\r\n");
      out.write("          '<input type=\"checkbox\" class=\"stayChk\" ' +\r\n");
      out.write("            'data-id=\"' + id + '\" data-name=\"' + escapeHtml(name) + '\" data-lat=\"' + lat + '\" data-lng=\"' + lng + '\" ' +\r\n");
      out.write("            (checked ? 'checked' : '') + ' style=\"margin-right: 8px;\">' +\r\n");
      out.write("          escapeHtml(name) +\r\n");
      out.write("          '<span class=\"muted tiny\" style=\"margin-left:4px;\"> (약 ' + dist.toFixed(2) + ' km)</span>' +\r\n");
      out.write("        '</label>';\r\n");
      out.write("\r\n");
      out.write("      stayList.appendChild(row);\r\n");
      out.write("\r\n");
      out.write("      const marker = new kakao.maps.Marker({ position: new kakao.maps.LatLng(lat, lng), map: map });\r\n");
      out.write("      stayMarkers.push(marker);\r\n");
      out.write("\r\n");
      out.write("      const iw = new kakao.maps.InfoWindow({\r\n");
      out.write("        content: '<div style=\"padding:8px;\"><b>' + escapeHtml(name) + '</b><br>약 ' + dist.toFixed(2) + ' km</div>'\r\n");
      out.write("      });\r\n");
      out.write("      kakao.maps.event.addListener(marker, 'click', () => iw.open(map, marker));\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    document.querySelectorAll('.stayChk').forEach(chk => {\r\n");
      out.write("      chk.addEventListener('change', () => {\r\n");
      out.write("        const id = Number(chk.dataset.id);\r\n");
      out.write("        if (chk.checked) {\r\n");
      out.write("          if (selected.some(x => x.id === id)) return;\r\n");
      out.write("          selected.push({ id: id, name: chk.dataset.name + ' (숙소)', lat: Number(chk.dataset.lat), lng: Number(chk.dataset.lng), day: 1, memo: '숙소' });\r\n");
      out.write("          \r\n");
      out.write("          // 숙소 선택 시 왼쪽 패널 닫혀있으면 열기\r\n");
      out.write("          const leftPanel = document.getElementById('leftTimeline');\r\n");
      out.write("          if (leftPanel.classList.contains('closed')) {\r\n");
      out.write("            toggleLeftPanel();\r\n");
      out.write("          }\r\n");
      out.write("        } else {\r\n");
      out.write("          selected = selected.filter(x => x.id !== id);\r\n");
      out.write("        }\r\n");
      out.write("        renderSelected();\r\n");
      out.write("        renderMapSelectedLayer(); \r\n");
      out.write("        \r\n");
      out.write("        // 삭제 후 리스트가 비어있으면 왼쪽 패널 닫기\r\n");
      out.write("        if(selected.length === 0) {\r\n");
      out.write("            const leftPanel = document.getElementById('leftTimeline');\r\n");
      out.write("            if (!leftPanel.classList.contains('closed')) {\r\n");
      out.write("              toggleLeftPanel();\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("      });\r\n");
      out.write("    });\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function savePlan() {\r\n");
      out.write("    if (selected.length < 1) {\r\n");
      out.write("      alert('저장할 장소가 없어.');\r\n");
      out.write("      return;\r\n");
      out.write("    }\r\n");
      out.write("    buildHiddenInputs();\r\n");
      out.write("    document.getElementById('saveForm').submit();\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function formatDuration(sec) {\r\n");
      out.write("    sec = Number(sec || 0);\r\n");
      out.write("    const h = Math.floor(sec / 3600);\r\n");
      out.write("    const m = Math.floor((sec % 3600) / 60);\r\n");
      out.write("    return (h > 0 ? (h + '시간 ') : '') + (m + '분');\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function formatDistance(m) {\r\n");
      out.write("    m = Number(m || 0);\r\n");
      out.write("    return (m >= 1000) ? ((m / 1000).toFixed(1) + ' km') : (m + ' m');\r\n");
      out.write("  }\r\n");
      out.write("\r\n");
      out.write("  function escapeHtml(str) { return String(str).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;').replaceAll(\"'\",'&#039;'); }\r\n");
      out.write("  function escapeXml(str) { return String(str ?? '').replaceAll('&','&amp;').replaceAll('\"','&quot;').replaceAll(\"'\",'&#039;').replaceAll('<','&lt;').replaceAll('>','&gt;'); }\r\n");
      out.write("</script>\r\n");
      out.write("\r\n");
      out.write("\n");
